   CSS Variables & Reset
   ==================== */

:root {
    --color-primary: #1a1a1a;
    --color-secondary: #f5f5f5;
    --color-accent: #d4af37;
    --color-text: #333;
    --color-text-light: #666;
    --color-border: #e0e0e0;
    --color-success: #4caf50;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 2rem;
    --spacing-lg: 3rem;
    --spacing-xl: 4rem;
    --transition: all 0.3s ease;
    --shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.12);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    font-size: 16px;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    color: var(--color-text);
    line-height: 1.6;
    background-color: #fff;
}

/* ====================
   Typography
   ==================== */

h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.2;
    margin-bottom: var(--spacing-sm);
}

h1 {
    font-size: 2.5rem;
}

h2 {
    font-size: 2rem;
    text-align: center;
    margin-bottom: var(--spacing-md);
}

h3 {
    font-size: 1.25rem;
}

p {
    margin-bottom: var(--spacing-sm);
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: var(--transition);
}

a:hover {
    color: var(--color-accent);
}

/* ====================
   Container & Layout
   ==================== */

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

/* ====================
   Header & Navigation
   ==================== */

.header {
    background-color: #fff;
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow);
}

.navbar-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo h1 {
    font-size: 1.5rem;
    margin: 0;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
    align-items: center;
}

.nav-links a {
    font-weight: 500;
    transition: var(--transition);
    font-size: 0.95rem;
}

.nav-links a:hover {
    color: var(--color-accent);
}

.cart-link {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
}

.cart-count {
    background-color: var(--color-accent);
    color: var(--color-primary);
    border-radius: 50%;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

/* ====================
   Hero Section
   ==================== */

.hero {
    background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
    color: #fff;
    padding: var(--spacing-xl) var(--spacing-md);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: 3rem;
    color: #fff;
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: rgba(255, 255, 255, 0.9);
}

/* ====================
   Buttons
   ==================== */

.btn {
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-align: center;
    display: inline-block;
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-primary);
}

.btn-primary:hover {
    background-color: #c9a227;
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-add-cart {
    background-color: var(--color-primary);
    color: #fff;
    width: 100%;
    padding: var(--spacing-sm);
    border-radius: 4px;
}

.btn-add-cart:hover {
    background-color: var(--color-accent);
    color: var(--color-primary);
}

/* ====================
   Sections
   ==================== */

.featured-section,
.deals-section,
.editorial-section {
    padding: var(--spacing-xl) var(--spacing-md);
}

.featured-section {
    background-color: #fff;
}

.deals-section {
    background-color: var(--color-secondary);
}

.editorial-section {
    background-color: #fff;
}

.section-subtitle {
    text-align: center;
    color: var(--color-text-light);
    font-size: 1.1rem;
    margin-bottom: var(--spacing-lg);
}

/* ====================
   Products Grid
   ==================== */

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-lg);
}

.product-card {
    background-color: #fff;
    border: 1px solid var(--color-border);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    overflow: hidden;
    height: 250px;
    background-color: var(--color-secondary);
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xs);
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-accent);
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
}

.product-description {
    font-size: 0.95rem;
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--spacing-sm);
}

.price {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-primary);
}

.product-footer .btn-add-cart {
    flex: 1;
    margin: 0;
}

/* ====================
   Deals Grid
   ==================== */

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-lg);
}

.deal-card {
    background-color: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    position: relative;
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-accent);
    color: var(--color-primary);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-weight: 700;
    z-index: 10;
}

.deal-image {
    height: 200px;
    overflow: hidden;
}

.deal-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.deal-info {
    padding: var(--spacing-md);
}

.deal-info h3 {
    margin-bottom: var(--spacing-xs);
}

.deal-info p {
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
}

.deal-link {
    color: var(--color-accent);
    font-weight: 600;
    transition: var(--transition);
}

.deal-link:hover {
    transform: translateX(4px);
}

/* ====================
   Editorial Grid
   ==================== */

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-lg);
}

.editorial-card {
    background-color: #fff;
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
}

.editorial-image {
    height: 250px;
    overflow: hidden;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-info {
    padding: var(--spacing-md);
}

.editorial-date {
    font-size: 0.85rem;
    color: var(--color-text-light);
    font-weight: 500;
}

.editorial-info h3 {
    margin: var(--spacing-sm) 0;
}

.editorial-info p {
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    line-height: 1.6;
}

.editorial-link {
    color: var(--color-accent);
    font-weight: 600;
    transition: var(--transition);
}

.editorial-link:hover {
    transform: translateX(4px);
}

/* ====================
   Newsletter Section
   ==================== */

.newsletter-section {
    background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
    color: #fff;
    padding: var(--spacing-xl) var(--spacing-md);
}

.newsletter-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--spacing-lg);
}

.newsletter-content h2 {
    color: #fff;
    text-align: left;
    margin: 0;
}

.newsletter-content p {
    color: rgba(255, 255, 255, 0.9);
    margin: 0;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    min-width: 350px;
}

.newsletter-form input {
    flex: 1;
    padding: var(--spacing-sm);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
}

.newsletter-form button {
    padding: var(--spacing-sm) var(--spacing-md);
}

/* ====================
   Footer
   ==================== */

.footer {
    background-color: var(--color-primary);
    color: #fff;
    padding: var(--spacing-xl) var(--spacing-md) var(--spacing-md);
}

.footer-content {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
    margin-bottom: var(--spacing-lg);
}

.footer-section h3 {
    color: #fff;
    margin-bottom: var(--spacing-md);
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: var(--spacing-xs);
}

.footer-section a {
    color: rgba(255, 255, 255, 0.8);
    transition: var(--transition);
}

.footer-section a:hover {
    color: var(--color-accent);
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-top: var(--spacing-md);
    text-align: center;
    color: rgba(255, 255, 255, 0.6);
}

/* ====================
   Responsive Design
   ==================== */

@media (max-width: 768px) {
    :root {
        font-size: 15px;
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-content p {
        font-size: 1rem;
    }

    .navbar-container {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .nav-links {
        gap: var(--spacing-md);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-content {
        flex-direction: column;
        text-align: center;
    }

    .newsletter-content h2 {
        text-align: center;
    }

    .newsletter-form {
        min-width: 100%;
        flex-direction: column;
    }

    .footer-content {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 480px) {
    :root {
        font-size: 14px;
    }

    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .hero-content p {
        font-size: 0.95rem;
    }

    .nav-links {
        gap: var(--spacing-sm);
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;
    }

    .newsletter-section {
        padding: var(--spacing-lg) var(--spacing-sm);
    }

    .newsletter-form {
        min-width: 100%;
    }
}

/* ====================
   Accessibility
   ==================== */

:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

