    :root {
        --color-text: #e0e0e0;
        --color-text-light: #999;
        --color-secondary: #2a2a2a;
        --color-border: #444;
    }

    body {
        background-color: #1a1a1a;
    }

    .header {
        background-color: #1a1a1a;
        border-bottom-color: var(--color-border);
    }

    .product-card {
        background-color: #2a2a2a;
    }

    .deal-card {
        background-color: #2a2a2a;
    }

    .editorial-card {
        background-color: #2a2a2a;
    }
}
